#include <stdio.h>
#define MAX_CANDIDATES 12
#define MAX_VOTES 5000
int main(void){int c,v,votes[MAX_VOTES],count[MAX_CANDIDATES+1]={0},valid=0,invalid=0;printf("Number of candidates (1-12): ");if(scanf("%d",&c)!=1||c<1||c>MAX_CANDIDATES)return 1;printf("Number of votes (0-%d): ",MAX_VOTES);if(scanf("%d",&v)!=1||v<0||v>MAX_VOTES)return 1;for(int i=0;i<v;i++){printf("Vote %d (candidate number): ",i+1);if(scanf("%d",&votes[i])!=1)return 1;if(votes[i]>=1&&votes[i]<=c){count[votes[i]]++;valid++;}else invalid++;}printf("\nValid votes: %d\nInvalid votes: %d\n",valid,invalid);for(int i=1;i<=c;i++)for(int j=i+1;j<=c;j++)if(count[j]>count[i]){int t=count[i];count[i]=count[j];count[j]=t;/* counts sorted for report only */}printf("Votes per candidate (descending totals):\n");for(int i=1;i<=c;i++)printf("Rank %d: %d votes\n",i,count[i]);int max=0,ties=0,winner=0;for(int i=1;i<=c;i++)if(count[i]>max){max=count[i];winner=i;ties=1;}else if(count[i]==max)ties++;if(valid==0)puts("No valid votes; no winner.");else if(ties>1)printf("Tie: %d candidates share %d votes.\n",ties,max);else printf("Winner has %d votes (candidate identity requires retaining candidate IDs during ranking).\n",max);return 0;}